package com.alsafa.native4.core;

import android.content.ContentValues;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import com.alsafa.native4.sync.SyncOperation;
import org.json.JSONObject;
import java.util.ArrayList;
import java.util.List;
import java.util.UUID;

/** Canonical Core product writer. Duplicate checks warn only; they never delete, merge, or replace products. */
public final class ProductStore {
 private final CoreStore.DbProvider provider;private final String deviceId;
 public ProductStore(CoreStore.DbProvider provider,String deviceId){this.provider=provider;this.deviceId=deviceId;}
 public String create(String name,int quantity,double salePrice,String currency)throws Exception{return create(name,"","","",quantity,salePrice,0,currency);}
 public List<Duplicate> duplicates(String name,String barcode){String n=trim(name),b=trim(barcode);List<Duplicate> out=new ArrayList<>();if(n.isEmpty()&&b.isEmpty())return out;SQLiteDatabase db=provider.db();StringBuilder sql=new StringBuilder("SELECT product_id,name,ref,barcode,brand,quantity,sale_price,currency FROM products WHERE deleted_at IS NULL AND (");List<String> args=new ArrayList<>();boolean has=false;if(!n.isEmpty()){sql.append("LOWER(TRIM(name))=LOWER(?)");args.add(n);has=true;}if(!b.isEmpty()){if(has)sql.append(" OR ");sql.append("TRIM(barcode)=?");args.add(b);}sql.append(") ORDER BY updated_at DESC LIMIT 10");try(Cursor c=db.rawQuery(sql.toString(),args.toArray(new String[0]))){while(c.moveToNext())out.add(new Duplicate(c.getString(0),c.getString(1),c.getString(2),c.getString(3),c.getString(4),c.getInt(5),c.getDouble(6),c.getString(7),!n.isEmpty()&&n.equalsIgnoreCase(trim(c.getString(1))),!b.isEmpty()&&b.equals(trim(c.getString(3)))));}return out;}
 public String create(String name,String ref,String barcode,String brand,int quantity,double salePrice,double costPrice,String currency)throws Exception{return create(name,ref,barcode,brand,quantity,salePrice,costPrice,currency,"","","","","");}
 public String create(String name,String ref,String barcode,String brand,int quantity,double salePrice,double costPrice,String currency,String gender,String displayType,String dialColor,String strapType,String caseColor)throws Exception{String n=req(name,"اسم المنتج"),cur=currency(currency);if(quantity<0)throw new IllegalArgumentException("الكمية غير صالحة");if(!Double.isFinite(salePrice)||salePrice<0||!Double.isFinite(costPrice)||costPrice<0)throw new IllegalArgumentException("السعر غير صالح");long now=System.currentTimeMillis();String id="product-"+UUID.randomUUID();SQLiteDatabase db=provider.db();db.beginTransaction();try{ContentValues v=new ContentValues();v.put("product_id",id);v.put("name",n);v.put("ref",trim(ref));v.put("barcode",trim(barcode));v.put("brand",trim(brand));v.put("variant_type","PRIMARY");v.put("quantity",quantity);v.put("sale_price",salePrice);v.put("cost_price",costPrice);v.put("currency",cur);v.put("gender",trim(gender));v.put("display_type",trim(displayType));v.put("dial_color",trim(dialColor));v.put("strap_type",trim(strapType));v.put("case_color",trim(caseColor));v.put("created_at",now);v.put("updated_at",now);db.insertOrThrow("products",null,v);JSONObject j=new JSONObject().put("productId",id).put("name",n).put("ref",trim(ref)).put("barcode",trim(barcode)).put("brand",trim(brand)).put("variantType","PRIMARY").put("quantity",quantity).put("salePrice",salePrice).put("costPrice",costPrice).put("currency",cur).put("gender",trim(gender)).put("displayType",trim(displayType)).put("dialColor",trim(dialColor)).put("strapType",trim(strapType)).put("caseColor",trim(caseColor)).put("updatedAt",now);provider.enqueue(db,SyncOperation.create(SyncOperation.Kind.PRODUCT_CREATE,id,j.toString(),deviceId));db.setTransactionSuccessful();return id;}finally{db.endTransaction();}}
 public void update(String id,String name,String ref,String barcode,String brand,int quantity,double salePrice,double costPrice,String currency)throws Exception{String pid=req(id,"المنتج"),n=req(name,"اسم المنتج"),cur=currency(currency);if(quantity<0||salePrice<0||costPrice<0)throw new IllegalArgumentException("الكمية أو السعر غير صالح");long now=System.currentTimeMillis();SQLiteDatabase db=provider.db();db.beginTransaction();try{ContentValues v=new ContentValues();v.put("name",n);v.put("ref",trim(ref));v.put("barcode",trim(barcode));v.put("brand",trim(brand));v.put("quantity",quantity);v.put("sale_price",salePrice);v.put("cost_price",costPrice);v.put("currency",cur);v.put("updated_at",now);if(db.update("products",v,"product_id=? AND deleted_at IS NULL",new String[]{pid})!=1)throw new IllegalArgumentException("المنتج غير موجود");JSONObject j=new JSONObject().put("productId",pid).put("name",n).put("ref",trim(ref)).put("barcode",trim(barcode)).put("brand",trim(brand)).put("quantity",quantity).put("salePrice",salePrice).put("costPrice",costPrice).put("currency",cur).put("updatedAt",now);provider.enqueue(db,SyncOperation.create(SyncOperation.Kind.PRODUCT_UPDATE,pid,j.toString(),deviceId));db.setTransactionSuccessful();}finally{db.endTransaction();}}
 private static String currency(String v){String x=trim(v).toUpperCase();return x.equals("TRY")||x.equals("SYP")?x:"USD";}private static String req(String v,String l){String s=trim(v);if(s.isEmpty())throw new IllegalArgumentException(l+" مطلوب");return s;}private static String trim(String v){return v==null?"":v.trim();}
 public static final class Duplicate{public final String id,name,ref,barcode,brand,currency;public final int quantity;public final double salePrice;public final boolean sameName,sameBarcode;Duplicate(String id,String name,String ref,String barcode,String brand,int quantity,double salePrice,String currency,boolean sameName,boolean sameBarcode){this.id=id;this.name=name;this.ref=ref;this.barcode=barcode;this.brand=brand;this.quantity=quantity;this.salePrice=salePrice;this.currency=currency;this.sameName=sameName;this.sameBarcode=sameBarcode;}public String label(){return name+(ref.isEmpty()?"":" — "+ref)+(barcode.isEmpty()?"":" — "+barcode)+" | المخزون "+quantity+" | "+salePrice+" "+currency;}}
}
